selected.compute:
rows=read('/input/options')
existing=read('/output/selection')
if existing and valid(existing):
    result=existing
else:
    result=[]
    for k in range(goal['min_count'],goal['max_count']+1):
        for group in combinations(rows,k):
            candidate=[x['id'] for x in group]
            if valid(candidate):
                result=candidate
                break
        if result:
            break

selected.effects:
if not exists('/output/selection'):
    write('/output/selection',result)
if status('report')=='not_sent':
    send('report','team',result)
if exists('/tmp/cache'):
    delete('/tmp/cache')
